package main

import (
    "fmt"
    "unicode/utf16"
    "unicode/utf8"
)

func main() {
    samples := []string{"cat", "\U0001F600", "e\u0301"}
    for _, text := range samples {
        fmt.Printf("%q utf16Units=%d codePoints=%d utf8Bytes=%d\n",
            text, len(utf16.Encode([]rune(text))),
            utf8.RuneCountInString(text), len(text))
    }
}
